    "cc-leilani-one-moment-everyone": {"name": "One Moment, Everyone", "cost": 2, "kind": "action", "rarity": "common", "quest": true, "champ": "leilani", "tags": [], "art": "key", "text": "Mitigate {mit} to every enemy. This turn the Tag Team bonus is 4 higher.", "flavor": "She doesn't shout. The whole landing stops anyway.", "mit": 14, "all": true, "tagUp": 4},
