    "cc-leilani-letter-to-pingsby": {"name": "Letter to Pingsby", "cost": 2, "kind": "action", "rarity": "uncommon", "quest": true, "champ": "leilani", "tags": [], "art": "envelope", "text": "Absorb {any} load. Hardened 1 (the next hit of the kind that just landed deals half).", "flavor": "The letter that started all this. She rewrote it nine times.", "abs": {"any": 9}, "hardened": 1},
    "cc-leilani-lighthouse-lock-two": {"name": "Lighthouse, Lock Two", "cost": 2, "kind": "action", "rarity": "rare", "quest": true, "champ": "leilani", "tags": [], "art": "padlock", "text": "Absorb {any} load. You and a teammate both answer the same question. Each right answer: Mitigate 12 if fast, 8 steady, 4 slow. Both right: Exposed 1 (the incident takes 50% more mitigation this turn). Solo: you answer, and a right answer counts twice.", "flavor": "Two keys, two hands, one door.", "abs": {"any": 10}, "ask": {"c": ["replication", "replag"], "type": "any", "who": "pair", "pool": {"card": 0.7, "champion": 0.2, "learned": 0.1}}, "speed": {"fast": {"mit": 12}, "steady": {"mit": 8}, "slow": {"mit": 4}}, "both": {"vuln": 1}, "concept": "replication", "solo2": true},
    "cc-leilani-one-thing-we-agree-on": {"name": "One Thing We All Agree On", "cost": 3, "kind": "action", "rarity": "rare", "quest": true, "champ": "leilani", "tags": [], "art": "coins", "text": "Mitigate {mit}. Explain it in your own words: Mitigate 3 more for each rubric point you hit. Pass (3+ points): Retry Budget 1 if fast, Circuit Breaker 1 if steady or slow.", "flavor": "Not the weather. Not the ferry. Something.", "mit": 12, "ask": {"c": ["consistency"], "type": "explain", "who": "self", "pool": {"card": 0.7, "champion": 0.2, "learned": 0.1}}, "perPoint": {"mit": 3}, "speed": {"fast": {"buffer": 1}, "steady": {"artifact": 1}, "slow": {"artifact": 1}}, "concept": "consistency"},
