    "cc-leilani-the-second-cup": {"name": "The Second Cup", "cost": 1, "kind": "action", "rarity": "rare", "quest": true, "champ": "leilani", "tags": [], "art": "atom", "text": "Absorb {any} load. The teammate you name answers a question. Right: they get Pre-Warmed 2 if fast, 1 if steady or slow, and the team Self-Healing 6 fast, 4 steady, 2 slow.", "flavor": "Poured before he asks. Every evening.", "abs": {"any": 6}, "ask": {"c": ["consistency", "replication"], "type": "any", "who": "ally", "pool": {"card": 0.7, "champion": 0.2, "learned": 0.1}}, "speed": {"fast": {"givePrewarm": 2, "regen": 6}, "steady": {"givePrewarm": 1, "regen": 4}, "slow": {"givePrewarm": 1, "regen": 2}}, "concept": "consistency"},
    "cc-suzu-recruit-anyone": {"name": "Recruit Anyone Standing Still", "cost": 1, "kind": "action", "rarity": "common", "quest": true, "champ": "suzu", "tags": [], "art": "checked-shield", "text": "Absorb {any} load. The teammate you name draws 1.", "flavor": "You stood still. You're in the Brigade now.", "abs": {"any": 4}, "giveDraw": 1},
