    "cc-suzu-brigades-first-rule": {"name": "The Brigade's First Rule", "cost": 2, "kind": "action", "rarity": "common", "quest": true, "champ": "suzu", "tags": [], "art": "perspective-dice-six-faces-random", "text": "Mitigate {mit}, +2 for each Pager Alert or Tech Debt in your hand.", "flavor": "Someone answers. Every time.", "mit": 8, "perPager": 2},
