    "cc-suzu-brigade-hq": {"name": "Brigade HQ", "cost": 2, "kind": "infra", "rarity": "uncommon", "quest": true, "champ": "suzu", "tags": [], "art": "dam", "text": "Infra. Absorb 4 load each turn, +2 for each Pager Alert or Tech Debt in your hand. Backpressure 2.", "flavor": "A corner of the arena, a table, a sign that says HQ.", "each": {"any": 4}, "eachPerPager": 2, "thorns": 2},
