    "cc-suzu-the-sticky-note": {"name": "The Sticky Note", "cost": 1, "kind": "action", "rarity": "rare", "quest": true, "champ": "suzu", "tags": [], "art": "puzzle", "text": "Absorb {any} load. The teammate you name answers a question. Right: the team Self-Healing 8 if fast, 5 steady, 3 slow, and they draw 1 if fast.", "flavor": "\"Thank you.\" Kept inside the armband.", "abs": {"any": 6}, "ask": {"c": ["oncall"], "type": "any", "who": "ally", "pool": {"card": 0.7, "champion": 0.2, "learned": 0.1}}, "speed": {"fast": {"regen": 8, "giveDraw": 1}, "steady": {"regen": 5}, "slow": {"regen": 3}}, "concept": "oncall"},
