    "cc-suzu-the-founding-question": {"name": "The Founding Question", "cost": 2, "kind": "action", "rarity": "rare", "quest": true, "champ": "suzu", "tags": [], "art": "globe", "text": "Mitigate {mit}. Explain it in your own words: Mitigate 3 more for each rubric point you hit. Pass (3+ points): pay off every Pager Alert and Tech Debt in your hand if fast, one if steady or slow.", "flavor": "Who actually answers? She founded a whole society to find out.", "mit": 10, "ask": {"c": ["nines"], "type": "explain", "who": "self", "pool": {"card": 0.7, "champion": 0.2, "learned": 0.1}}, "perPoint": {"mit": 3}, "speed": {"fast": {"clearCard": {"card": "any", "mine": true, "n": 10}}, "steady": {"clearCard": {"card": "any", "mine": true, "n": 1}}, "slow": {"clearCard": {"card": "any", "mine": true, "n": 1}}}, "concept": "nines"},
