    "cc-gong-waiting-for-tea": {"name": "Waiting for Tea", "cost": 0, "kind": "action", "rarity": "common", "quest": true, "champ": "gong", "tags": [], "art": "hourglass", "text": "Draw 1. +1 Stale.", "flavor": "He has been waiting for some time.", "draw": 1, "stale": 1},
